import pathlib,json,hashlib
R=pathlib.Path(__file__).resolve().parent
def load(n):return json.loads((R/n).read_text())
def save(n,x):(R/n).write_text(json.dumps(x,indent=2)+'\n')
source=load('source-analysis.json');coverage=load('coverage.json');rank=load('rank-confirmation.json')
inventory=json.loads((R.parent/'source/inventory.json').read_text());selected=load('selection-results.json');accepted=load('delivery/accepted.json')
trials=next(p['trials'] for p in load('conditional-shortcut-results.json') if p['stage']=='delivered' and p['template']=='P' and p['subgroup']=='n=2' and p['strategy']=='largest_coefficient_after_constant')
indexed={p['sample_index']:p for p in trials};base=max(q[':db/id'] for q in inventory['questions'])+100
selection=[]
for sc in selected['scenarios']:
 ts=[indexed[i-base] for i in sc['draws'] if i is not None and i-base in indexed]
 selection.append({'scenario':sc['scenario'],'generated_selected':sc['generated_selected'],'n2_selected':len(ts),'cue_correct':sum(t['correct'] for t in ts),'total_draws':sc['draw_count']})
save('delivery-selection-summary.json',{'captured_basis':inventory['basis'],'publication_preparation_present':(R.parent/'publication/preparation.json').exists(),'stages':{'raw':len(load('samples.json')),'accepted':len(accepted),'runner_input':5,'runner_accepted':5,'fresh_n2_input':35,'fresh_n2_accepted':35},'selection_scenarios':selection,'interpretation':'The read-only shared filter preserves every sampled P/R bank and every tested n2 cue case; only duplicate B records are removed. Positive moderate weights preserve n2 exposure under within-band sampling. Unconfigured, zero-moderate and seen-history cases change eligibility as documented. Actual later database IDs, inventory, learner histories and configured policy are unavailable; exact live frequencies are not asserted.','rejection':'generate has no rejection/resampling loop; it selects offset from nonzero k+offset candidates, derives a bank from distinct eligible divisor/factor pairs, builds and emits each record. No rejection by response role.','evidence':['samples.json','delivery/accepted.json','rank-delivery/accepted.json','selection-results.json','conditional-shortcut-results.json']})
save('scope-results.json',{'source_basis':source['source_refs'],'judgment':'The normal P/R/B families retain two integrable power terms, coefficient magnitude one on the nonconstant term, one arbitrary C and the observed moderate response contracts. P/B exponents 2..6 and R exponents -3/2,-5/2,-7/2 use the same simple power-rule stages. R positive-variable condition makes radical identities explicit. Signs, signed constants, variable renaming and ordering are legitimate variations.','limits':'General positive radicals and reciprocal-plus-radical pairs with unlabelled difficulty are replay-only; hard fourth-root item lacks a captured response contract. q-71173 is mathematical replay only because fields are absent. This conservative family is defensible for moderate practice; no unsupported progression claimed.','boundaries':'96 explicit sign/constant/order/exponent boundary records plus random coverage include all declared exponents, all twelve signed constants, both signs/orders, and x/y/t where eligible. Exponent -1 and other operators are excluded.','passed':True})
cf=[]
for n,records in [('counterfactual-results.json','counterfactual-records.json'),('reciprocal-counterfactual-results.json','reciprocal-counterfactual-records.json')]:
 for p in load(n):
  cf.append({'kind':p['kind'],'change':p['label'],'expected':'Change the response after applying the power rule to changed evidence.' if p['kind']=='relevant' else 'Preserve the mathematical response, allowing consistent variable substitution.','observed':p['response_relationship']+'; independent derivative/solution checks, rendered pair and native complete-bank or blank cross-response outcomes agree.','status':'passed','justification':'Tutorial 701 sum rule and prerequisite power rule make exponents, signs and constants relevant; term order and consistent notation do not change the integral. The polynomial exponent pair preserves wrong divisors 2 and 8 by updating their derived relative factors.','sample_refs':[records,n,'grader-input-final.json','grading-final.json','render-full/input.json','render-full/rendering.json']})
cf.append({'kind':'irrelevant','change':'Change competing polynomial divisors while fixing the entire integrand.','expected':'Preserve the correct integral and explanation while changing relative coefficient rank.','observed':'Paired n=3..6 low/high divisor controls preserve answers; native full-bank checks pass. n=2 high-divisor control confirms valid alternative bank.','status':'passed','justification':'Incorrect-option assignments are incidental to sum-rule integration; their role need not stay fixed.','sample_refs':['assignment-control-records.json','assignment-control-results.json','grader-input-final.json','grading-final.json']})
probes=[]
for stage in ['raw','delivered']:
 for t in 'PR':
  for strategy in ['first','last','old_unit_numerator_cue']:
   p=next(p for p in load('conditional-shortcut-results.json') if p['stage']==stage and p['template']==t and p['subgroup']=='all' and p['strategy']==strategy)
   probes.append({'cue':'display position' if strategy!='old_unit_numerator_cue' else 'constant match plus unit numerator/single-digit denominator','subgroup':stage+' '+t,'scope':'within_template','strategy':strategy,'correct':p['correct'],'total':p['total'],'baseline':0.2,'disposition':'not_predictive','conclusion':'Baseline is uniform five-choice guessing. No fixed answer position; former polynomial typography cue leaves multiple candidates across all 420 allowed revised assignments. A finite sample does not exclude every cue.','sample_refs':['conditional-shortcut-results.json','samples.json','delivery/accepted.json','revised-domain-results.json']})
for report in rank['reports']:
 probes.append({'cue':'quadratic prompt and maximum absolute power coefficient after matching the constant','subgroup':report['file']+' P exponent 2','scope':'other_recognizable_subgroup','strategy':rank['strategy'],'correct':report['correct'],'total':report['total'],'baseline':report['baseline_after_constant'],'disposition':'defect','conclusion':'Baseline averages uniform choice among the 2 or 3 constant-matched options, after granting correct constant integration. Fresh success 30/35 versus 0.395 baseline; exact assignment-domain success 66/84 versus 5/12 baseline. This partial predictor bypasses integration of the nonconstant summand; counterexamples are retained and the heuristic is not claimed perfect.','sample_refs':[report['file'],'rank-confirmation.json','grader-input-final.json','grading-final.json','rank-render-records.json']})
pv={'learner_operation':source['learner_operation'],'fixed_features':[{'feature':'Exactly two simple integrable power terms, no exponent -1','justification':'e-371 and tutorial 701 establish splitting and power integration; logarithms or additional terms change skill/workload.'},{'feature':'One correct response; radio bank of five or blank with printed C','justification':'Captured q-71167/q-71169 radios and q-133291 blank establish the response contracts.'},{'feature':'Coefficient magnitude one for nonconstant integrands in conservative moderate families','justification':'General constant-factor integration is introduced in the subsequent tutorial 703 and knowledge point.'}],'answer_roles':[{'role':'Correct expression, including sign/constant/exponent','eligible_variation':'Change signed constant, nonconstant exponent/sign and term order within the same method.','observed':'All declared exponents, 12 signed constants, both signs/orders observed pre/post filtering.'},{'role':'Correct choice position and competing errors','eligible_variation':'Shuffle choices and change which wrong coefficient/divisor accompanies each constant; preserve mathematical key.','observed':'All five positions and four omitted cells observed in each radio profile. Old typography cue removed, but n=2 maximum-magnitude cue is structurally favored.'},{'role':'Integration variable and external C','eligible_variation':'Rename variable consistently; retain omitted C only where externally printed.','observed':'x/y/t on radio, t on derivative blank; rename/order pairs preserve response.'}],'coverage':[{'case':stage+' '+t,'sample_refs':['samples.json','delivery/accepted.json','coverage.json'],'result':str(d)} for stage in ['raw','delivered'] for t,d in coverage[stage].items()],'counterfactuals':cf,'shortcut_probes':probes,'delivery':{'stages_examined':['generator parameter eligibility and no rejection/resampling branch','requested moderate difficulty','actual shared normalization and validation','inventory and batch deduplication','fresh/usable candidates and weighted/unconfigured learner selection'],'sample_refs':['samples.json','runner-batch.json','delivery/accepted.json','batch-delivery/accepted.json','rank-delivery/accepted.json','delivery-selection-summary.json','selection-results.json'],'result':'360→328 (32 B duplicates), runner 5→5, fresh n2 subgroup 35→35; all sampled P/R decision cases survive. Weighted selection retains the cue in eligible n2 cases. No live database mutation or publication.'},'limitations':['Captured inventory basis 5277 only; later inventory and actual learner history/policy are unavailable. Selection uses synthetic appended entity IDs and documented eligibility assumptions.','The fresh runner batch contains R/B only; independent samples supply P coverage.','The rank heuristic is imperfect: 5/35 fresh cases fail; 18/84 domain assignments fail. This is a demonstrated structural bias, not a claim that answer rank is fixed.','No finite audit proves absence of every shortcut. Missing original fields/keys and derivative premise are recorded in source-analysis.json.']}
save('pedagogical-variation.json',pv)
pkg=R.parent/'workspace';after={str(p.relative_to(pkg)):hashlib.sha256(p.read_bytes()).hexdigest() for p in pkg.rglob('*') if p.is_file()};save('package-after.json',after);assert after==load('package-before.json')
grader=load('grading-final.json');assert grader['database_writes']==0 and grader['documented_unresolved_checks']==0
for p in ['render-full/rendering.json','render-rank/rendering.json']:assert load(p)['passed']
assert len(load('render-full/rendering.json')['cases'])==31
checks={}
def check(name,status,paths,details):checks[name]={'status':status,'evidence_paths':paths,'details':details}
check('source_replay','passed',['source-replay.json','source-replay-results.json','source-parameter-records.json'],'Replayed seven source cases and all 21 captured choices; missing controls, inferred keys and restored derivative premise explicitly documented. Canonical e-371 parameter point independently verified.')
check('math','passed',['math-results.json','revised-domain-results.json','rank-holdout-records.json','revision_probes.py','confirm_rank.py'],'475 sampled/boundary/controlled records passed independent exact prompt, bank and solution checks; 420 revised bank assignments passed exact choice differentiation; 35 fresh cue cases also independently checked.')
check('variety','failed',['coverage.json','rank-confirmation.json','delivery-selection-summary.json'],'Declared slots and decision cases survive delivery, but quadratic banks systematically reward a coefficient-magnitude cue.')
check('scope','passed',['scope-results.json','source-analysis.json','boundaries.json'],'Normal moderate generation retains the two-term sum-rule/power-rule workload. Incomplete or unlabelled source families remain explicitly bounded replay cases.')
check('grading','passed',['grader-input-final.json','grading-final.json'],f"Native learner grading passed {grader['accepted_checks']} accepted and {grader['rejected_checks']} rejected responses, including equivalent/factored blank entries, wrong entries, complete banks, counterfactuals and cue-selected responses.")
check('rendering','passed',['visual-inspection.json','render-full/rendering.json','render-rank/rendering.json'],'Actual UI rendered 31 representative/controlled/runner records and 2 fresh cue examples; screenshots inspected for notation, controls and worked solutions.')
check('packaging','passed',['packaging-results.json','package-before.json','package-after.json','commands.md'],'Exact Python 3.13.5 / empty third-party dependency declaration, deterministic replay, relocation, CLI rejection and zero external outputs checked. Complete package file hashes unchanged.')
check('decision_variation','failed',['pedagogical-variation.json','rank-confirmation.json','grading-final.json','delivery-selection-summary.json'],'Relevant and irrelevant controlled pairs pass. Former typography shortcut repaired; new quadratic coefficient-rank shortcut succeeds 30/35 fresh delivered cases and 66/84 equiprobable assignment cases without integrating the quadratic term.')
result={'verdict':'revise','summary':'Quadratic items retain a strong incidental coefficient-rank cue: it earned credit on 30/35 fresh delivered questions and succeeds on 66/84 eligible bank assignments. Other checks passed; package unchanged.','source_analysis':{k:source[k] for k in ['skill','reasoning_steps','invariants','permitted_variations','source_refs','evidence_paths']},'checks':checks,'findings':[{'kind':'decision_shortcut','description':'In P-grid questions with a printed quadratic term, integrate only the constant and choose the matching option with the largest absolute cubic coefficient. Incorrect divisors are drawn from 2,4,5,6,7,8,9; six yield smaller coefficients than the correct 1/3. This makes the response-producing cue correct on 66/84 equally likely bank assignments (78.6%), versus 41.7% random choice after matching the constant. Fresh delivered confirmation is 30/35 (85.7%), versus 39.5% conditional chance. The heuristic is imperfect, but the repeatable advantage comes from incidental distractor assignments and bypasses integrating the quadratic term.','source_refs':['e-371 / e4a94ca8-82ee-5776-a46d-b735d4ab60fb: termwise power-rule integration','q-71167 / 9e4827b1-c8af-5e0e-a92c-bab0c6f19c7d','tutorial 701 / 207bbd12-158a-58be-b000-82cace6dcdde: integral of a sum equals sum of the integrals','generate/principles.md: meaningful variation and incidental answer-producing actions'],'reproduction':'Run confirm_rank.py with job Python -B (seed 94172863, count 480); filter its 35 P,n=2 records using check_delivery.py; run confirm_rank.py --analyze and check-engine grader-input-final.json grading-final.json. All 35 survive; 30 cue selections earn credit. First case 3db312c4-57f1-5974-89ee-5815dc9dceaa asks integral(-x^2+5)dx; matching +5x leaves coefficients -1/4 and -1/3, so the larger-magnitude cue succeeds. See rank-confirmation.json, rank-delivery/accepted.json and render-rank/question-001.png.','requested_change':'Revise polynomial distractor assignment probabilities or eligible coefficient sets so quadratic correctness is not strongly predicted by maximum coefficient magnitude after constant matching. Preserve source replay and mathematical workload; rerun conditional rank probes against fresh delivered samples and verify grading/rendering. Merely showing that another rank is possible does not resolve the demonstrated bias.'}]}
save('result.json',result)
print(json.dumps({'verdict':result['verdict'],'checks':{k:v['status'] for k,v in checks.items()},'package_unchanged':True,'selection':selection}))
